function xp_action(array $u):string{xp_csrf();$a=xp_text('xp_action',40);if($a==='activate'){if(!in_array($u['role'],['platform_super_admin','school_admin'],true))throw new RuntimeException('Administrator required.');xp_install();if(function_exists('px_install'))px_install();sisInstall();ssMigrate();ix_install();return 'Experience and installed workspace tables activated. Existing records retained.';}if($a==='tour_done'&&!xp_ready()){$_SESSION['xp_tour_done']=true;return 'Walkthrough complete. Activate Experience to persist account progress.';}if(!xp_ready())throw new RuntimeException('Ask an administrator to activate Experience first.');if($a==='tour_done'){q('INSERT IGNORE INTO xp_progress(tenant_id,user_id,step) VALUES(?,?,?)',[(int)($u['tenant_id']??0),$u['id'],'tour']);return 'Walkthrough saved. Replay it any time from the header.';}
if($a==='reset_account')return xp_reset_account($u);if($a==='renew_free')return xp_renew_free($u);if($a==='checkout'){$_SESSION['xp_checkout']=xp_checkout($u);return 'Secure checkout created. Open it below, then verify your completed payment.';}if($a==='verify')return xp_verify($u,(int)xp_text('payment_id',20));
if($a==='platform_settings'){if($u['role']!=='platform_super_admin')throw new RuntimeException('Platform administrator required.');$origin=rtrim(xp_text('origin',1000),'/');$url=parse_url($origin);if(!filter_var($origin,FILTER_VALIDATE_URL)||($url['scheme']??'')!=='https'||isset($url['query'])||isset($url['fragment'])||isset($url['user'])||isset($url['pass']))throw new RuntimeException('Enter the canonical HTTPS installation address, without a query string.');$policy=xp_text('trial_policy',20);if(!in_array($policy,['plans','payment'],true))throw new RuntimeException('Invalid trial policy.');$enabled=isset($_POST['registrations'])?'1':'0';if($enabled==='1'&&!g('SELECT id FROM saas_plans WHERE active=1 LIMIT 1'))throw new RuntimeException('Configure at least one active plan in SaaS Control Centre first.');xp_tx(function()use($origin,$policy,$enabled){foreach(['origin'=>$origin,'trial_policy'=>$policy,'registrations'=>$enabled,'join'=>isset($_POST['join'])?'1':'0'] as $key=>$value)q('INSERT INTO xp_config VALUES(?,?) ON DUPLICATE KEY UPDATE value=VALUES(value)',[$key,$value]);});audit('experience.platform.settings');return 'Public signup, school approval and subscription settings saved.';}
if($a==='demo_relay')return px_demo_relay($u);if($a==='demo_refresh'){if($u['role']!=='platform_super_admin'||xp_text('demo_reset_confirm',10,false)!=='yes')throw new RuntimeException('Platform administrator must confirm replacing shared fictional demo changes.');if(xp_text('demo_name',100)!==v23secret('xp_demo_name'))throw new RuntimeException('Enter the configured isolated demo database name.');return xp_demo_refresh();}if($a==='demo_config'){if($u['role']!=='platform_super_admin')throw new RuntimeException('Platform administrator required.');return xp_demo_provision();}
if($u['role']!=='school_admin')throw new RuntimeException('School administrator required.');$tid=(int)$u['tenant_id'];
if($a==='school_access'){q('INSERT INTO xp_schools(tenant_id,join_code,listed,requests_enabled) VALUES(?,?,?,?) ON DUPLICATE KEY UPDATE listed=VALUES(listed),requests_enabled=VALUES(requests_enabled)',[$tid,bin2hex(random_bytes(16)),isset($_POST['listed'])?1:0,isset($_POST['requests_enabled'])?1:0]);return 'Your school’s request policy saved. Pending users still require identity, role and link verification.';}
if($a==='review_request'){return xp_tx(function()use($u,$tid){$r=q("SELECT r.*,u.active FROM xp_requests r JOIN users u ON u.id=r.user_id AND u.tenant_id=r.tenant_id WHERE r.tenant_id=? AND r.id=? FOR UPDATE",[$tid,(int)xp_text('request_id',20)])->fetch();if(!$r||$r['status']!=='pending'||$r['active'])throw new RuntimeException('Request unavailable or already reviewed.');if(xp_text('identity_checked',10,false)!=='yes')throw new RuntimeException('Verify the person’s identity and requested role before review.');$decision=xp_text('decision',20);if(!in_array($decision,['approved','rejected'],true))throw new RuntimeException('Invalid decision.');$note=xp_text('review_note',1000);$role=xp_text('approved_role',30);if(!isset(xp_join_roles()[$role]))throw new RuntimeException('Choose an allowed school role; administrator status is never self-registered.');if($decision==='approved'){$temporary='Start-'.bin2hex(random_bytes(10)).'!';$actual=in_array($role,['driver','warden'],true)?'staff':$role;q('UPDATE users SET active=1,role=?,password_hash=? WHERE tenant_id=? AND id=?',[$actual,password_hash($temporary,PASSWORD_DEFAULT),$tid,$r['user_id']]);$_SESSION['xp_initial_credential']=['email'=>(string)g('SELECT email FROM users WHERE tenant_id=? AND id=?',[$tid,$r['user_id']]),'password'=>$temporary];if(in_array($role,['driver','warden'],true)){if(!xp_has('op_roles'))throw new RuntimeException('Activate Operations before granting this duty.');q('INSERT IGNORE INTO op_roles VALUES(?,?,?)',[$tid,$r['user_id'],$role]);}}q('UPDATE xp_requests SET status=?,reviewed_by=?,review_note=?,temp_expires_at=DATE_ADD(NOW(),INTERVAL 3 DAY) WHERE tenant_id=? AND id=?',[$decision,$u['id'],$note,$tid,$r['id']]);audit('experience.request.'.$decision,'user',(string)$r['user_id']);return 'Request '.$decision.'. Verified family/student record links, teacher allocations and driver/warden duty assignments must be added separately.';});}
throw new RuntimeException('Unsupported Experience action.');}
function xp_welcome(array $u):void{$platform=$u['role']==='platform_super_admin';echo '<section class="xp-welcome" id="xpWelcome"><div><span class="xp-eyebrow">A CLEARER START</span><h1>'.($platform?'Build a welcoming platform.':'Your school, set up with care.').'</h1><p>Practical steps. Clear explanations. A confident school community.</p></div></section>';if(!xp_ready()){echo '<section class="xp-panel"><h2>Activate the new experience</h2><p>Back up your database first. This prepares additive Experience and installed workspace tables, retaining existing school records.</p>';if(in_array($u['role'],['school_admin','platform_super_admin'],true))xp_form('activate','Activate Experience & installed workspaces');else echo '<p>Your school administrator can activate the new experience.</p>';echo '</section>';return;}
if($platform){if(isset($_SESSION['xp_initial_credential'])){$credential=$_SESSION['xp_initial_credential'];echo '<div class="xp-notice"><strong>Copy once: verified account recovery</strong><p>'.e($credential['email']).'<br><code>'.e($credential['password']).'</code></p><p>Expires in 72 hours; a personal password is required at first sign-in. Share only with the verified person through a secure process.</p></div>';unset($_SESSION['xp_initial_credential']);}echo '<section class="xp-panel"><h2>Public school registration</h2><p>Use your real active SaaS plans. Set each cycle’s prices and trial days in <a href="?s=saas">SaaS Control Centre</a>; configure the platform Paystack gateway in <a href="?s=integrations">Integrations</a>. New-school subscription enforcement applies to self-service schools; existing schools keep their current billing workflow.</p>';xp_form('platform_settings','Save signup policy',['origin'=>['Canonical HTTPS installation URL (including subdirectory if used)','url',xp_setting('origin')],'trial_policy'=>['Trial policy',['plans'=>'Use configured plan trial days','payment'=>'Require verified payment before access'],xp_setting('trial_policy','plans')],'registrations'=>['Enable new-school self-service registration','check',xp_setting('registrations')==='1'],'join'=>['Enable school-approved member self-registration','check',xp_setting('join','1')==='1']]);echo '<p>Current registration: '.e(xp_setting('registrations')==='1'?'enabled':'disabled').'; member requests: '.e(xp_setting('join','1')==='1'?'enabled':'disabled').'; trial policy: '.e(xp_setting('trial_policy','plans')).'. Uncheck an option to disable it.</p></section><section class="xp-panel"><h2>Isolated connected demo</h2><p>Create an empty MariaDB database in cPanel whose name ends <code>_demo</code>. Use dedicated credentials. It must differ from the live application database. This action refuses populated databases and seeds only fictional accounts/records. Keep backups of the live application; no live records are copied. Provision once, then visitors can select a role on the login page.</p>';xp_form('demo_config','Validate empty database & build connected demo',['demo_host'=>['Demo database host','text','localhost'],'demo_name'=>['Empty dedicated database name ending _demo','text'],'demo_user'=>['Dedicated database username','text'],'demo_pass'=>['Dedicated database password','password','',false],'demo_confirm'=>['I confirm this is an empty, isolated database for fictional shared demo data','check']]);echo '</section>';echo '<section class="xp-panel"><h2>Keep the demo fresh</h2><p>Refresh rebuilds only the marked, separate sandbox and replaces all visitor changes. Use a quiet period. Unknown additional tables cause a refusal. The live school database is never copied or cleared.</p>';xp_form('demo_refresh','Replace fictional demo data',['demo_name'=>['Type the configured dedicated demo database name','text'],'demo_reset_confirm'=>['I understand all shared fictional demo changes will be replaced','check']]);echo '<p>Optional cPanel cron: <code>php /path/to/public_html/experience_demo_refresh.php --confirm-isolated-demo</code>. Choose a quiet daily time in Africa/Lagos so date-sensitive demo attendance and manifests stay useful.</p></section>';echo '<section class="xp-panel"><h2>Optional dedicated demo video relay</h2><p>A contracted or self-hosted TURN relay can connect demo classrooms across different networks. Use a separate demo relay with provider quotas. Live school relay secrets are never copied to the sandbox.</p>';xp_form('demo_relay','Configure dedicated demo relay',['turn_url'=>['Demo TURN URL, for example turns:relay.example.ng:5349','text'],'turn_secret'=>['Dedicated demo relay shared secret','password'],'demo_relay_confirm'=>['I confirm this relay is dedicated to the public sandbox and has suitable quotas','check']]);echo '</section>';xp_recovery_form($u);xp_module_audit($u);return;}
if($u['role']!=='school_admin'){echo '<section class="xp-panel"><h2>Your first school day</h2><ol><li>Check your profile name and school.</li><li>Open your role workspace from the home page.</li><li>Ask the administrator to verify missing class, child or duty assignments.</li><li>Review privacy guidance and use the walkthrough whenever you need help.</li></ol><a class="btn" href="?s=workspace">Open my overview →</a></section>';return;}
$view=$_GET['view']??'journey';echo '<nav class="xp-tabs"><a href="?s=welcome">Setup journey</a><a href="?s=welcome&view=access">People & access</a><a href="?s=welcome&view=billing">Subscription</a><a href="?s=welcome&view=modules">Workspace health</a></nav>';
if($view==='billing'){echo '<section class="xp-panel"><h2>Your subscription</h2>';xp_billing($u);echo '</section>';return;}
if($view==='access'){echo '<section class="xp-panel" id="xpActions"><h2>Invite, verify, connect.</h2><p>Administrators can <a href="?s=portal_users">create accounts directly</a>, or let people request access below. Self-registration creates an inactive account. Approval does not infer family links, class allocations or duty assignments. Never approve based only on a matching name.</p>';$currentAccess=q('SELECT * FROM xp_schools WHERE tenant_id=?',[$u['tenant_id']])->fetch()?:[];xp_form('school_access','Save school request policy',['requests_enabled'=>['Accept school member requests','check',!empty($currentAccess['requests_enabled'])],'listed'=>['Show school name and state in the public school selector','check',!empty($currentAccess['listed'])]]);$setting=q('SELECT * FROM xp_schools WHERE tenant_id=?',[$u['tenant_id']])->fetch();if(isset($_SESSION['xp_initial_credential'])){$credential=$_SESSION['xp_initial_credential'];echo '<div class="xp-notice" role="status"><strong>Copy this temporary credential once.</strong><p>'.e($credential['email']).'<br><code>'.e($credential['password']).'</code></p><p>Give it only to the verified person through your school’s secure process. The password chosen on the pending request has been replaced. It expires in 72 hours. A new personal password is required at first sign-in.</p></div>';unset($_SESSION['xp_initial_credential']);}if($setting)echo '<p>Requests '.($setting['requests_enabled']?'enabled':'disabled').'. Share this private invitation code only with your school community: <code>'.e($setting['join_code']).'</code>. School listing is '.($setting['listed']?'public':'private').'.</p>';$rows=q('SELECT r.id,u.name,u.email,r.requested_role,r.reference_note,r.status FROM xp_requests r JOIN users u ON u.id=r.user_id AND u.tenant_id=r.tenant_id WHERE r.tenant_id=? ORDER BY r.id DESC LIMIT 100',[$u['tenant_id']])->fetchAll();op_table($rows,['Request','Name','Email','Requested role','Reference','Status']);xp_form('review_request','Record verified decision',['request_id'=>['Pending request ID','number'],'identity_checked'=>['I verified identity, control of the email address, school relationship and appropriate role','check'],'decision'=>['Decision',['approved'=>'Approve','rejected'=>'Reject']],'approved_role'=>['Verified role',xp_join_roles()],'review_note'=>['Verification evidence and follow-up record links','textarea']]);xp_recovery_form($u);echo '<p><a href="?s=portal_links">Connect approved accounts to verified records →</a> · <a href="?s=academics">Assign teacher classes →</a> · <a href="?s=operations&area=transport">Assign drivers to routes →</a></p></section>';return;}
if($view==='modules'){xp_module_audit($u);return;}
echo '<section class="xp-panel" id="xpSetup"><div class="xp-section-head"><div><span class="xp-eyebrow">YOUR SCHOOL LAUNCH PLAN</span><h2>One purposeful step at a time.</h2></div><button type="button" class="theme-toggle" data-xp-tour>Take the walkthrough</button></div><p>Start with your school identity and academic structure. Then connect people, configure Finance, and test with a small group before inviting your wider community.</p><ol class="xp-journey">';foreach(xp_checks($u) as $i=>$check)echo '<li class="'.($check['done']?'complete':'').'""><span>'.($check['done']?'✓':($i+1)).'</span><div><strong>'.e($check['title']).'</strong><p>'.e($check['why']).'</p><small>'.($check['done']?'Configuration found; review as your school changes.':'Needs attention before dependent workflows can be trusted.').'</small></div><a href="?s='.e($check['url']).'">'.($check['done']?'Review':'Set up').' →</a></li>';echo '</ol></section><section class="xp-panel"><h2>Prepare installed workspaces</h2><p>Activation is additive. It installs the database tables required by the Learning, Operations, Services and Intelligence files already included in the release. It does not enable live AI, external messages, payment credentials or prepaid spending.</p>';xp_form('activate','Prepare all installed workspace tables');echo '</section>';}
function xp_module_audit(array $u):void{echo '<section class="xp-panel"><span class="xp-eyebrow">INSTALLED WORKSPACE HEALTH</span><h2>Every menu should lead somewhere useful.</h2><p>These checks inspect installed files and database activation. They do not prove credentials, licence arrangements, assignments or historical data are complete. External services remain explicit configuration steps.</p><div class="xp-action-grid">';foreach(xp_catalog() as [$group,$route,$title,$description,$table,$files]){$missing=array_values(array_filter($files,fn($f)=>!is_file(__DIR__.'/'.$f)));$active=match($route){'learning'=>lp_ready(),'family'=>pp_ready(),'operations'=>op_ready(),'services'=>sv_ready(),'intelligence'=>ix_ready(),default=>xp_has($table)};$ready=!$missing&&$active;echo '<article class="xp-audit"><small>'.e($group).'</small><h3>'.e($title).'</h3><p>'.e($description).'</p><span class="xp-status '.($ready?'ready':'attention').'">'.($ready?'Files and tables available':($missing?'Restore missing files':'Activation needed')).'</span>';if($missing)echo '<p>'.e(implode(', ',$missing)).'</p>';if($u['role']!=='platform_super_admin')echo '<p><a href="?s='.e($ready?$route:'welcome').'">'.($ready?'Open workspace':'Prepare workspace').' →</a></p>';echo '</article>';}echo '</div><h3>Configuration that cannot be inferred</h3><p>Verified account links, teacher allocations, dates and term weights, school fees, gateway credentials, message consent, provider templates, legal/privacy review and cron jobs must be configured and checked by the responsible school/platform team. Public sites require approved content; custom domains require DNS/TLS ownership verification.</p><p>Duplicate legacy menu aliases now lead to the current workspaces. Roadmap/experimental controls are kept out of the simplified school-owner navigation; the audit guide documents their scope instead of representing them as installed capabilities.</p></section>';}

function xp_reset_account(array $u):string{if(!in_array($u['role'],['school_admin','platform_super_admin'],true)||xp_text('identity_checked',10,false)!=='yes')throw new RuntimeException('Administrator must verify identity and control of the email address.');$id=(int)xp_text('user_id',20);$note=xp_text('review_note',1000);$credential=xp_tx(function()use($u,$id,$note){$person=q('SELECT * FROM users WHERE id=? AND active=1 FOR UPDATE',[$id])->fetch();if(!$person||!$person['tenant_id']||$person['role']==='platform_super_admin'||($u['role']!=='platform_super_admin'&&((int)$person['tenant_id']!==(int)$u['tenant_id']||$person['role']==='school_admin')))throw new RuntimeException('Account recovery is outside your scope. School owners need platform-team verification.');$password='Start-'.bin2hex(random_bytes(10)).'!';q('UPDATE users SET password_hash=? WHERE id=?',[password_hash($password,PASSWORD_DEFAULT),$id]);q("INSERT INTO xp_requests(tenant_id,user_id,requested_role,reference_note,status,must_change,temp_expires_at,reviewed_by,review_note) VALUES(?,?,?,'Administrator-assisted account recovery','approved',1,DATE_ADD(NOW(),INTERVAL 3 DAY),?,?) ON DUPLICATE KEY UPDATE status='approved',must_change=1,temp_expires_at=VALUES(temp_expires_at),reviewed_by=VALUES(reviewed_by),review_note=VALUES(review_note)",[$person['tenant_id'],$id,$person['role'],$u['id'],$note]);audit('experience.account.recovery','user',(string)$id);return ['email'=>$person['email'],'password'=>$password];});$_SESSION['xp_initial_credential']=$credential;return 'Temporary recovery credential created. Copy it once and share only through your verified school process.';}
function xp_recovery_form(array $u):void{echo '<details class="xp-panel"><summary>Help someone sign in · verified account recovery</summary><p>Verify the person’s identity and control of the email address before issuing a credential. School administrators can recover active member accounts in their school. A school owner requires the platform team. The old password is replaced, the temporary credential expires after 72 hours, and a new personal password is required at first sign-in.</p>';$people=$u['role']==='platform_super_admin'?q("SELECT id,CONCAT(name,' · ',email,' · school ',tenant_id) label FROM users WHERE active=1 AND tenant_id IS NOT NULL AND role='school_admin' ORDER BY name LIMIT 500")->fetchAll():q("SELECT id,CONCAT(name,' · ',email) label FROM users WHERE tenant_id=? AND active=1 AND role IN ('teacher','parent','student','staff','admissions') ORDER BY name LIMIT 500",[$u['tenant_id']])->fetchAll();$options=[];foreach($people as $person)$options[$person['id']]=$person['label'];xp_form('reset_account','Issue verified temporary credential',['user_id'=>['Account',$options],'identity_checked'=>['Identity and control of this email have been verified','check'],'review_note'=>['Recovery verification evidence; do not enter identity-document numbers','textarea']]);echo '</details>';}
